package com.vandorlabs.neoforge.light;
import com.google.gson.*;
import com.vandorlabs.redstone.ChannelList;
import io.netty.buffer.*;
import java.nio.file.*;
import net.minecraft.core.BlockPos;
/** Bounded wire matrix and actual Source menu flags/byte counts. No world access. */
public final class LightSettingsChecks {
 private static int checks;private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Light settings: "+why);}
 private static void reject(ByteBuf buffer){try{NativeLightSettingsEdit.decode(buffer);throw new AssertionError("Accepted malformed Light settings");}catch(IllegalArgumentException expected){checks++;}finally{buffer.release();}}
 public static void main(String[] args)throws Exception{var picker=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();for(var element:picker){var row=element.getAsJsonObject();int choice=row.get("choice").getAsInt();need(NativeLightPickerPolicy.selectable(choice,false)==row.get("on").getAsBoolean()&&NativeLightPickerPolicy.selectable(choice,true)==row.get("off").getAsBoolean(),"actual Source filter choice="+choice);}need(picker.size()==893,"source filter coverage");int roundtrips=0;for(int count:new int[]{0,2,64}){int[] values=new int[count];for(int i=0;i<count;i++)values[i]=i+1;var channels=ChannelList.of(values);for(int level=0;level<16;level++)for(int trigger=0;trigger<3;trigger++)for(int flags=0;flags<8;flags++)for(int layout=0;layout<3;layout++)for(int offset:new int[]{-15,0,15}){var edit=new NativeLightSettingsEdit(new BlockPos(-12,-2,18),77,new NativeLightEdit(78,-1,level,(flags&1)!=0,0,trigger,(flags&2)!=0,layout,(flags&4)!=0,offset),channels);var wire=Unpooled.buffer();try{edit.encode(wire);need(wire.readableBytes()==30+4*count,"bounded exact body length");need(NativeLightSettingsEdit.decode(wire).equals(edit)&&wire.readableBytes()==0,"native packet full roundtrip");roundtrips++;}finally{wire.release();}}}
 var valid=new NativeLightSettingsEdit(BlockPos.ZERO,7,new NativeLightEdit(78,-1,15,true,0,2,true,2,true,-15),ChannelList.of(1,2));var buffer=Unpooled.buffer();valid.encode(buffer);for(int length=0;length<buffer.readableBytes();length++)reject(buffer.copy(0,length));reject(Unpooled.wrappedBuffer(new byte[NativeLightSettingsEdit.MAX_BYTES+1]));for(int[] mutation:new int[][]{{24,16},{25,8},{26,3},{27,3},{28,16},{28,240},{29,65},{29,255}}){var bad=buffer.copy();bad.setByte(mutation[0],mutation[1]);reject(bad);}for(int index:new int[]{8,12,20,30}){var bad=buffer.copy();bad.setInt(index,-1);reject(bad);}var trailing=Unpooled.buffer();trailing.writeBytes(buffer,0,buffer.readableBytes());trailing.writeByte(0);reject(trailing);buffer.release();
 var source=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();for(var value:source.getAsJsonArray("wire")){var row=value.getAsJsonObject();int count=row.get("channels").getAsInt();need(row.get("bytes").getAsInt()==42+4*count,"actual Source wire count");}System.out.println("Native Light settings PASS checks="+checks+" roundtrips="+roundtrips+" picker=893 sourceBody=42+4N nativeBody=30+4N maxBytes=286 malformed-before-allocation");}
}
